<?php
if(!defined('WP_CLI')||!WP_CLI||DB_HOST!=='amsec-next-db'||!in_array(DB_NAME,['wordpress','wordpress69'],true)){exit(1);}
use AmazingPlugins\Security\Rules\RuleCatalog;
use AmazingPlugins\Security\Rules\RulePage;
$path=dirname(AMAZING_SECURITY_FILE).'/assets/rule-manifest.json';$old=file_get_contents($path);$before=get_option('amsec_content_state');$http=static function(){throw new RuntimeException('Unexpected external rule request.');};$die=static fn()=>static function($m,$t,$a){throw new RuntimeException('denied:'.($a['response']??500));};add_filter('pre_http_request',$http);add_filter('wp_die_handler',$die);
try{
$catalog=new RuleCatalog(dirname(AMAZING_SECURITY_FILE));$packs=$catalog->status(time());if(array_column($packs,'status')!==['recent','recent','recent']||array_map(static fn($p)=>count($p['ids']),array_values($packs))!==[17,4,2]){throw new RuntimeException('Installed catalog failed.');}
foreach([0,wp_create_user('amsec-rules-sub-'.bin2hex(random_bytes(4)),bin2hex(random_bytes(16)))] as $id){if(is_wp_error($id)){throw new RuntimeException('Subscriber fixture failed.');}if($id){(new WP_User($id))->set_role('subscriber');}wp_set_current_user($id);try{(new RulePage())->render();throw new LogicException('Unauthorized rules page accepted.');}catch(RuntimeException $e){if($e->getMessage()!=='denied:403'){throw $e;}}finally{if($id){require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($id);}}}
wp_set_current_user(1);ob_start();(new RulePage())->render();$html=ob_get_clean();foreach(['Rule information','AS-PHP-017','AS-HTML-003','AS-REST-002','Observe-only','independent proof','staffed maintenance','Metadata recently reviewed'] as $text){if(!str_contains($html,$text)){throw new RuntimeException('Rule page content missing.');}}
$m=json_decode($old,true);$m['packs']['files']['reviewed_at']='2026-01-01';file_put_contents($path,wp_json_encode($m));if($catalog->status(time())['files']['status']!=='overdue'){throw new RuntimeException('Stale metadata shown as recent.');}$m['packs']['files']['version']='changed';file_put_contents($path,wp_json_encode($m));if($catalog->status(time())['files']['status']!=='unknown'){throw new RuntimeException('Changed record shown as valid.');}if(get_option('amsec_content_state')!==$before){throw new RuntimeException('Rule page altered old findings.');}
echo 'Installed rule catalog, 23 stable IDs, administrator/guest/subscriber gates, overdue/unknown statuses, no external request and unchanged report state passed.'.PHP_EOL;
}finally{file_put_contents($path,$old);remove_filter('pre_http_request',$http);remove_filter('wp_die_handler',$die);wp_set_current_user(1);}
